export function chooseImmuneUnit(state,unit){
 const steps=immuneMissions[state.mission]?.steps;if(!steps||state.finished||state.confirmed||!steps[state.step]?.choices.includes(unit))return state;
 return {...state,confirmed:steps[state.step].correct===unit,errors:state.errors+(steps[state.step].correct===unit?0:1)};
}
export function advanceImmuneState(state){if(!state.confirmed||state.finished)return state;const next=state.step+1;return {...state,step:next,confirmed:false,finished:next>=immuneMissions[state.mission].steps.length}}
